import{_ as i,I as a,g as e,j as n}from"./chunks/framework.YqoK2ckR.js";const c=JSON.parse('{"title":"vibecoding","description":"","frontmatter":{},"headers":[],"relativePath":"notes/AI生产力工具/vibecoding.md","filePath":"notes/AI生产力工具/vibecoding.md"}'),p={name:"notes/AI生产力工具/vibecoding.md"};function l(t,s,h,o,d,r){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="vibecoding" tabindex="-1">vibecoding <a class="header-anchor" href="#vibecoding" aria-label="Permalink to &quot;vibecoding&quot;">​</a></h1><p>这玩意怎么说呢，不好评价</p><h2 id="分清几个概念" tabindex="-1">分清几个概念 <a class="header-anchor" href="#分清几个概念" aria-label="Permalink to &quot;分清几个概念&quot;">​</a></h2><p>AI的很多概念其实都挺简单：</p><h3 id="prompt-提示词" tabindex="-1">Prompt(提示词) <a class="header-anchor" href="#prompt-提示词" aria-label="Permalink to &quot;Prompt(提示词)&quot;">​</a></h3><p>就是你给AI发的文字，可以去看吴恩达的prompt课程</p><h3 id="大模型" tabindex="-1">大模型 <a class="header-anchor" href="#大模型" aria-label="Permalink to &quot;大模型&quot;">​</a></h3><p>大模型就是直接和你对话，读取prompt，从prompt生成回答的东西，比如ChatGPT</p><p>高质量编程建议使用<code>opus4.6</code>,<code>gpt5.5</code></p><p>简单任务(比如不涉及特别重要的业务)：<code>Kimi2.5</code>,<code>Composer2.5</code>,<code>Deepseek-v4-flash</code>,<code>Deepseek-v4-pro</code>,<code>GLM5.1</code>等，反正你刷多了，推特首页全你妈是老登的测评和资本家的吹嘘。</p><p>我做blender和正经任务肯定是opus,网页小游戏，纯前端用的是Composer2.5和Deepseek</p><p>老马要推出Grok了，高低得尝尝咸淡～</p><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>AI一开始只能和我们对话，根据AI输出的答案操作电脑的就是Agent工具，比如读文件，写入文件，在终端输入命令并执行</p><p>一般的工具都有Agent模式和Plan模式，Plan就是先和AI商量好要干什么，确定计划后再执行，防止改烂了或AI没有理解我们的需求，在opencode里，对应<code>Build</code>和<code>Plan</code>模式</p><h3 id="skills" tabindex="-1">SKILLS <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;SKILLS&quot;">​</a></h3><p>以前我们只有通过prompt来规范AI的行为，为了规范，prompt往往很长，且有大量重复</p><p>何不放一个.md文件来规范它？让AI自己读取规范需求？</p><p>SKILL就这样诞生了——当然这只是简单的理解</p><p>SKILL是按需求加载的，它要求<code>SKILL.md</code>开头有<code>name</code>,<code>description</code>,一个告诉AI这个SKILL叫做什么名字，一个描述这个SKILL，比如：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: pdf-processing</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 从 PDF 中提取文本和表格，填写表单，并合并文档</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># PDF 处理</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 使用场景</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">当需要对 PDF 文件进行操作时使用，例如：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 提取 PDF 文本或表格数据</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 填写 PDF 表单</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 合并多个 PDF 文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 提取文本</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 使用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pdfplumber\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 提取文本型 PDF 内容  </span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 扫描版 PDF 需配合 OCR 工具  </span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 填写表单</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 读取 PDF 表单字段  </span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 按输入数据填充并生成新文件</span></span></code></pre></div><p>当你在做网站前端的vibecoding时，AI不会阅读你的pdf-processing，因为你的description告诉AI这个是做pdf处理的，与现在任务无关，这就节省了token和开发者的时间</p><h2 id="常用的工具" tabindex="-1">常用的工具 <a class="header-anchor" href="#常用的工具" aria-label="Permalink to &quot;常用的工具&quot;">​</a></h2><ul><li>Claude Code(最常用)</li><li>Codex</li><li>cursor</li><li>opencode</li></ul><p>我用的是cursor,因为支持银联和支付宝，也用opencode，但是通常处理小任务</p><p>Codex十分强大，我在等它出Linux版本，其它操作系统的用户可以去体验一下</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><p>没有基础不建议vibecoding,别变成拿着localhost在社交平台上发疯的沙毕。</p><p>基础教程：<a href="https://datawhalechina.github.io/easy-vibe/zh-cn/appendix/1-computer-fundamentals/vibe-coding-fullstack.html" target="_blank" rel="noreferrer">链接</a></p><p>最最起码的：知道每个文件分别负责什么，如果这个都判断不出就别做了。</p>`,30)])])}const g=i(p,[["render",l]]);export{c as __pageData,g as default};
